using System;
using System.Collections.Generic;

namespace AimranDataScienceLab.Core.Domain.Analytics;

/// <summary>
/// Represents insights and analysis results.
/// Auto-generated by AI Assistant and manual analysis by Data Analysts.
/// </summary>
public class InsightReport
{
    public Guid Id { get; set; }
    public Guid ProjectId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;

    public InsightType Type { get; set; }
    public Guid? SourceDatasetId { get; set; }

    public Insight[] Insights { get; set; } = Array.Empty<Insight>();
    public Visualization[] Visualizations { get; set; } = Array.Empty<Visualization>();
    public string? Recommendations { get; set; }

    public int Relevance { get; set; } // 1-10 score
    public bool IsApproved { get; set; }
    public Guid? ApprovedByUserId { get; set; }

    public Guid CreatedByUserId { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime UpdatedAt { get; set; }
}

public enum InsightType
{
    Distribution,
    Correlation,
    Trend,
    Anomaly,
    Cluster,
    Outlier,
    TimeSeries,
    Composite,
    AutoGenerated,
    Manual
}

public class Insight
{
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string[] SupportingData { get; set; } = Array.Empty<string>();
    public double ConfidenceScore { get; set; } // 0-1
    public string BusinessImpact { get; set; } = string.Empty;
}

public class Visualization
{
    public string Title { get; set; } = string.Empty;
    public VisualizationType Type { get; set; }
    public string ChartJson { get; set; } = string.Empty;
    public string[] RelatedColumns { get; set; } = Array.Empty<string>();
}

public enum VisualizationType
{
    BarChart,
    LineChart,
    ScatterPlot,
    Histogram,
    BoxPlot,
    HeatMap,
    PieChart,
    TimeSeriesChart,
    CorrelationMatrix,
    Custom
}

/// <summary>
/// Dashboard for Data Analysts.
/// Can contain multiple visualizations and KPIs.
/// </summary>
public class AnalyticsDashboard
{
    public Guid Id { get; set; }
    public Guid ProjectId { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;

    public DashboardWidget[] Widgets { get; set; } = Array.Empty<DashboardWidget>();
    public DashboardFilter[] Filters { get; set; } = Array.Empty<DashboardFilter>();

    public bool IsPublic { get; set; }
    public Guid? OwnerId { get; set; }

    public DateTime CreatedAt { get; set; }
    public DateTime UpdatedAt { get; set; }
}

public class DashboardWidget
{
    public Guid Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public WidgetType Type { get; set; }

    public Guid? InsightReportId { get; set; }
    public Guid? VisualizationId { get; set; }

    public int PositionX { get; set; }
    public int PositionY { get; set; }
    public int Width { get; set; }
    public int Height { get; set; }

    public Dictionary<string, object> Configuration { get; set; } = new();
    public DateTime? LastRefreshedAt { get; set; }
    public TimeSpan? RefreshInterval { get; set; }
}

public enum WidgetType
{
    Chart,
    Table,
    KPI,
    Gauge,
    Map,
    Text,
    Metric,
    Alert,
    Custom
}

public class DashboardFilter
{
    public string ColumnName { get; set; } = string.Empty;
    public FilterOperator Operator { get; set; }
    public object? Value { get; set; }
    public string DisplayLabel { get; set; } = string.Empty;
}

public enum FilterOperator
{
    Equals,
    NotEquals,
    GreaterThan,
    LessThan,
    Between,
    In,
    Contains,
    StartsWith,
    EndsWith
}

/// <summary>
/// Report generated for stakeholders.
/// </summary>
public class AnalyticsReport
{
    public Guid Id { get; set; }
    public Guid ProjectId { get; set; }
    public string Title { get; set; } = string.Empty;

    public Guid[] InsightReportIds { get; set; } = Array.Empty<Guid>();
    public string ExecutiveSummary { get; set; } = string.Empty;
    public string[] Recommendations { get; set; } = Array.Empty<string>();

    public DateTime GeneratedAt { get; set; }
    public Guid GeneratedByUserId { get; set; }

    public string? PdfUrl { get; set; }
    public string? MarkdownUrl { get; set; }
}
